return items.map(item => {
  const originalText = item.json.output;

  if (typeof originalText !== 'string') {
    return {
      json: {
        error: 'El campo "output" no existe o no es un texto',
        original: originalText
      }
    };
  }

  let textContent = originalText;
  let metadata = {};
  let parseError = false;

  // 🔹 1. Extracción del bloque JSON interno
  const startIdx = originalText.lastIndexOf('{');
  const endIdx = originalText.lastIndexOf('}');

  if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
    const jsonString = originalText.substring(startIdx, endIdx + 1);
    try {
      metadata = JSON.parse(jsonString);
      // Extraemos solo el mensaje de texto (lo que está antes del JSON)
      textContent = originalText.substring(0, startIdx).trim();
    } catch (e) {
      // Intento de rescate si el JSON tiene errores de formato
      try {
        const rescuedJson = jsonString
          .replace(/[\u0000-\u001F\u007F-\u009F]/g, "")
          .trim();
        metadata = JSON.parse(rescuedJson);
        textContent = originalText.substring(0, startIdx).trim();
      } catch (e2) {
        parseError = true;
      }
    }
  }

  // 🔹 2. Normalización del score_total (asegurar que sea número)
  let rawScore = metadata.score_total;
  let normalizedScore = 0;
  if (rawScore !== undefined && rawScore !== null) {
    if (typeof rawScore === 'string') {
      const match = rawScore.match(/(\d+(\.\d+)?)/);
      normalizedScore = match ? parseFloat(match[1]) : 0;
    } else {
      normalizedScore = Number(rawScore);
    }
  }

  // 🔹 3. Limpieza del mensaje de texto
  let cleaned = textContent
    .replace(/<[^>]*>/g, '') // elimina HTML
    .replace(/\t+/g, ' ')    // reemplaza tabs
    .replace(/[ ]{2,}/g, ' ') // elimina espacios duplicados
    .trim();

  // 🔹 4. Lógica de división por partes
  const minCharsPerPart = 300;
  const partes = [];

  const dividirPorPuntoMasCercano = (texto, cantidadPartes) => {
    const longPorParte = Math.floor(texto.length / cantidadPartes);
    const cortes = [];
    let lastIndex = 0;

    for (let i = 1; i < cantidadPartes; i++) {
      let corte = texto.lastIndexOf('.', i * longPorParte);
      if (corte === -1 || corte <= lastIndex + 50) {
        corte = texto.lastIndexOf(';', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50)
          corte = texto.lastIndexOf(',', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50)
          corte = texto.lastIndexOf(' ', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50)
          corte = i * longPorParte;
      }
      cortes.push(corte);
      lastIndex = corte;
    }

    const secciones = [];
    let inicio = 0;
    for (let i = 0; i < cortes.length; i++) {
      secciones.push(texto.slice(inicio, cortes[i] + 1).trim());
      inicio = cortes[i] + 1;
    }
    secciones.push(texto.slice(inicio).trim());
    return secciones;
  };

  if (cleaned.length > 0) {
    if (cleaned.length <= minCharsPerPart * 1.2) {
      partes.push(cleaned);
    } else if (cleaned.length <= minCharsPerPart * 2.2) {
      partes.push(...dividirPorPuntoMasCercano(cleaned, 2));
    } else {
      partes.push(...dividirPorPuntoMasCercano(cleaned, 3));
    }
  }

  // 🔹 5. Construcción del objeto final con campos extraídos
  const output = {
    // Campos de calificación/metadata
    nombre_lead: metadata.nombre_lead || "N/A",
    nombre_empresa: metadata.nombre_empresa || "N/A",
    tamano_empresa: metadata.tamano_empresa || "N/A",
    ruta_detectada: metadata.ruta_detectada || "NO_DEFINIDA",
    score_total: normalizedScore,
    decision: metadata.decision || "PENDIENTE",
    nivel_interes: metadata.nivel_interes || "N/A",
    metadata_valida: !parseError
  };

  // Añadir las partes del texto
  partes.forEach((parte, index) => {
    output[`parte_${index + 1}`] = parte;
  });

  return { json: output };
});

